    faqs: [{ q: "Does UV Resin replace a clear casting resin for every clear part?", a: "No. The site publishes UV Resin and Epoxy Clear Casting Resin as separate product routes. The choice requires review of the actual finished part, required material role and current product-specific documentation." }, { q: "What makes a clear-resin comparison useful?", a: "Describe whether the requirement is a clear finish, doming or encapsulation role, or a clear contained cast; then add the finished-item details, quantity, required appearance, any stated equipment context and delivery location." }],
    sections: [{ heading: "Do not let the word clear decide the product", body: ["Both routes can appear in a clear-resin search, but the site publishes them for different purposes. UV Resin is the UV/LED-curable route for jewellery, encapsulation, doming and speciality coating work. Epoxy Clear Casting Resin is the separately published two-part route for clear contained casting.", "A clear appearance request alone does not establish the right product. Identify the finished item and whether its requirement is a finish, doming or encapsulation role versus a contained casting role before comparing documentation."] }, { heading: "Use the product role to frame the discussion", body: ["Where UV/LED curing is part of the stated requirement and the application matches the published UV Resin context, start with the UV Resin product page and current TDS. Where the requirement is a clear contained cast, start with the separate Clear Casting Resin page and its current TDS.", "This distinction does not prescribe a processing method, confirm depth capability, state an exposure schedule or guarantee clarity. It keeps the buyer discussion aligned to the documented product route."] }, { heading: "Prepare a clear, commercial enquiry", body: ["State the finished part, whether the material is intended for clear finishing, doming, encapsulation or a contained cast, required appearance, expected quantity, delivery location and any stated specification. Include UV/LED equipment context only when the UV route is being considered.", "The supplier discussion should verify the actual product role. Do not transfer technical values, compatibility assumptions or cure details from one clear-resin product to another."] }],
