    faqs: [{ q: "What should be included in a UV Resin RFQ?", a: "Include the intended application, industry or end use, finished product, required clear or finished appearance, stated UV/LED equipment requirement if known, expected quantity and delivery location." }, { q: "Does this guide confirm stock, lead time, sample policy or suitability?", a: "No. It helps prepare a factual enquiry. Availability, lead time, samples, suitability and any performance expectation must be confirmed for the actual requirement." }],
    sections: [{ heading: "Start with the actual material role", body: ["Identify whether the finished product needs the published UV Resin role: UV/LED-curable jewellery, encapsulation, doming or speciality coating work. If the requirement is instead an open self-levelling decorative surface, a clear contained cast or a reinforced FRP component, start with the separate published product route before preparing an enquiry.", "State the end product and visible-finish requirement in factual terms. Do not rely on a broad request for 'transparent UV resin' as a substitute for the finished-product, equipment and documentation context."] }, { heading: "Use the current UV Resin document", body: ["The current UV Resin TDS is the product-specific reference for the published epoxy-acrylate UV/LED route. It should be reviewed alongside the actual finished-product requirement. Follow the TDS for storage and handling information rather than transferring advice from another UV, epoxy or polyester product.", "The current listing publishes a 200 kg pack and 1,000 kg MOQ. These are commercial reference points only; they do not imply stock availability, lead time, sample policy, delivery commitment or a guarantee of suitability."] }, { heading: "UV Resin quotation checklist", body: ["Provide the intended application, industry or end use, finished product, clear or finished appearance requirement, any stated UV/LED equipment requirement, expected quantity and delivery location. Include a drawing, purchase specification or relevant product reference only when it is available.", "This guide does not provide exposure times, curing schedules, mixing directions, operating advice or a performance guarantee. The purpose is to make the selection and commercial conversation specific enough for product-data review."] }],
